#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int MODULUS = 998244353;
    int gcdVal, xVal, yVal;

    function<void(int, int)> calculateGCD = [&](int a, int b) {
        if (b == 0) {
            gcdVal = a; xVal = 1; yVal = 0;
        } else {
            calculateGCD(b, a % b);
            int tempX = xVal - a / b * yVal;
            xVal = yVal;
            yVal = tempX;
        }
    };

    auto getInverse = [&](int a) {
        calculateGCD(a, MODULUS);
        return xVal < 0 ? xVal + MODULUS : xVal;
    };

    int nVal, mVal, kVal;
    cin >> nVal >> mVal >> kVal;
    int mInverse = getInverse(mVal);

    std::vector<long long> dpArr(kVal + 1, 0);
    dpArr[0] = 1;

    for (int i = 0; i < kVal; i++) {
        for (int d = kVal - 1; d >= 0; d--) {
            if (dpArr[d] != 0) {
                dpArr[d + 1] = (dpArr[d + 1] + dpArr[d] * (nVal - d)) % MODULUS;
                dpArr[d] = (dpArr[d] * d) % MODULUS;
            }
        }
    }

    long long probPower = 1;
    long long totalAns = 0;
    for (int d = 1; d <= kVal; d++) {
        probPower = probPower * mInverse % MODULUS;
        totalAns = (totalAns + dpArr[d] * probPower) % MODULUS;
    }

    cout << totalAns << "\n";

    return 0;
}
